    double *avg16L = aw_s->avg16L;
    double *avg16R = aw_s->avg16R;
    double *avg8L = aw_s->avg8L;
    double *avg8R = aw_s->avg8R;
    double *avg4L = aw_s->avg4L;
    double *avg4R = aw_s->avg4R;
