    double *avg2R = aw_s->avg2R;
    double *post32L = aw_s->post32L;
    double *post32R = aw_s->post32R;
    double *post16L = aw_s->post16L;
    double *post16R = aw_s->post16R;
    double *post8L = aw_s->post8L;
    double *post8R = aw_s->post8R;
    double *post4L = aw_s->post4L;
    double *post4R = aw_s->post4R;
